import{_ as e,o as s,c as t,a2 as l}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"恢复","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/recovery.md","filePath":"zh/manual/recovery.md"}'),n={name:"zh/manual/recovery.md"};function i(o,a,d,c,r,p){return s(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="恢复" tabindex="-1">恢复 <a class="header-anchor" href="#恢复" aria-label="Permalink to &quot;恢复&quot;">​</a></h1><h2 id="崩溃产物" tabindex="-1">崩溃产物 <a class="header-anchor" href="#崩溃产物" aria-label="Permalink to &quot;崩溃产物&quot;">​</a></h2><p>内核捕获故障时，会在报告路径之前先写入一条崩溃记录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; sysdiag               -&gt; crash records (crashlog + dumpinfo)</span></span>
<span class="line"><span>ush&gt; crashlog              (the recorded exceptions of this boot)</span></span>
<span class="line"><span>ush&gt; dumpinfo              (core-dump status)</span></span>
<span class="line"><span>ush&gt; dmesg                 (the kernel log around the event)</span></span></code></pre></div><p><code>crashtest panic|exc|...</code>（仅 classic/direct——刻意不设为向导按钮）注入受控故障来演练这套机制。</p><h2 id="a-b-逃生通道" tabindex="-1">A/B 逃生通道 <a class="header-anchor" href="#a-b-逃生通道" aria-label="Permalink to &quot;A/B 逃生通道&quot;">​</a></h2><p>损坏的槽位绝不会让机器变砖：</p><ol><li>重启；GRUB 菜单提供强制槽位 A / 强制槽位 B 项。</li><li>引导另一个槽位，然后在其中执行：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update rollback</span></span></code></pre></div><h2 id="winre-风格的恢复流程" tabindex="-1">WinRE 风格的恢复流程 <a class="header-anchor" href="#winre-风格的恢复流程" aria-label="Permalink to &quot;WinRE 风格的恢复流程&quot;">​</a></h2><ol><li>引导任意 Open Cube OS ISO（救援工具包就是安装程序）。</li><li>接上故障盘（<code>-drive if=ide,file=broken.img</code>）。</li><li>只查看、不写入：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool               lsblk / parted / fsck - all read-only here</span></span>
<span class="line"><span>ush&gt; files                   browse the damaged volume once mounted</span></span></code></pre></div><ol start="4"><li>用 <code>files</code> 恢复数据（cp 到一块已挂载的 FAT32 卷）。</li><li>必要时重装：<code>install &lt;dev&gt;</code>（单系统）或 <code>disk-tool</code> 的 A/B 管理器（更新盘形态）。</li></ol><h2 id="崩溃转储子系统" tabindex="-1">崩溃转储子系统 <a class="header-anchor" href="#崩溃转储子系统" aria-label="Permalink to &quot;崩溃转储子系统&quot;">​</a></h2><p>内核核心转储会落入崩溃服务的产物区域，带寄存器与栈状态；<code>dumpinfo</code> 报告其位置。<a href="./../internals/crash-dump.html">../internals/crash-dump.md</a> 页面介绍了格式与保留策略。</p><h2 id="看门狗" tabindex="-1">看门狗 <a class="header-anchor" href="#看门狗" aria-label="Permalink to &quot;看门狗&quot;">​</a></h2><p>看门狗服务守护系统存活；卡死的内核会触发复位，下次启动的 crashlog 会显示看门狗事件及卡死上下文。<code>watchdog</code>（classic / <code>sysdiag</code> 表）报告状态；内部机制见 <a href="./../internals/watchdog.html">../internals/watchdog.md</a>。</p>`,17)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
